12	import java.time.Instant;
13	import java.time.temporal.ChronoUnit;
14	import java.util.ArrayList;
15	import java.util.Comparator;
16	import java.util.List;
17	import java.util.Locale;
18	
19	/**
20	 * 跑道临时关闭巡检与开放决策服务：状态流转、幂等、并发与事务边界在此实现。
21	 */
22	@Service
23	public class RunwayService {
24	
25	    private static final String SCOPE_REPORT = "report";
26	    private static final String SCOPE_ASSESSMENT = "assessment";
27	    private static final String SCOPE_REOPEN = "reopen";
28	
29	    private final RunwayEventRepository eventRepository;
30	    private final InspectionRepository inspectionRepository;
31	    private final AssessmentRepository assessmentRepository;
32	    private final NotamRepository notamRepository;
33	    private final WeatherRepository weatherRepository;
34	    private final RunwayProperties properties;
35	    private final IdempotencyExecutor idempotencyExecutor;
36	    private final Clock clock;
37	
38	    public RunwayService(RunwayEventRepository eventRepository,
39	                         InspectionRepository inspectionRepository,
40	                         AssessmentRepository assessmentRepository,
41	                         NotamRepository notamRepository,
42	                         WeatherRepository weatherRepository,
43	                         RunwayProperties properties,
44	                         IdempotencyExecutor idempotencyExecutor,
45	                         Clock clock) {
46	        this.eventRepository = eventRepository;
47	        this.inspectionRepository = inspectionRepository;
48	        this.assessmentRepository = assessmentRepository;
49	        this.notamRepository = notamRepository;
50	        this.weatherRepository = weatherRepository;
51	        this.properties = properties;
52	        this.idempotencyExecutor = idempotencyExecutor;
53	        this.clock = clock;
54	    }
55	
56	    /**
57	     * 接报：即触发临时关闭并同步发布关闭通告；requestId 幂等；同一跑道唯一进行中事件。
58	     */
59	    public ReportResponse report(ReportRequest request) {
60	        String fingerprint = fingerprint(SCOPE_REPORT, request.requestId(), request.runwayId(),
61	                request.eventType().name(), request.reportedAt().toString());
62	        try {
63	            return idempotencyExecutor.execute(SCOPE_REPORT, request.requestId(), fingerprint,
64	                    () -> doReport(request), ReportResponse.class);
65	        } catch (DuplicateKeyException e) {
66	            ReportResponse replayed = idempotencyExecutor.tryReplay(SCOPE_REPORT, request.requestId(),
67	                    fingerprint, ReportResponse.class);
68	            if (replayed != null) {
69	                return replayed;
70	            }
71	            if (isActiveEventConflict(e)) {
72	                throw ApiException.conflict("RUNWAY_ACTIVE_EVENT_EXISTS", "同一跑道已存在进行中的关闭事件");
73	            }
74	            throw e;
75	        }
76	    }
77	
78	    private ReportResponse doReport(ReportRequest request) {
79	        Instant now = clock.instant();
80	        Instant closedAt = request.reportedAt();
81	        Instant deadline = closedAt.plus(properties.inspectionStartLimitMinutes(), ChronoUnit.MINUTES);
82	        RunwayEvent event = new RunwayEvent(0L, request.runwayId(), request.eventType(), EventStatus.CLOSED,
83	                request.reportedAt(), closedAt, deadline, false, null, request.requestId(), now, now);
84	        event = eventRepository.insert(event, 1);
85	        String notamNo = "NTM-C-" + event.id();
86	        notamRepository.insert(new NotamRecord(0L, event.id(), event.runwayId(), NotamAction.CLOSE,
87	                notamNo, closedAt));
88	        return new ReportResponse(event.id(), event.runwayId(), event.status().name(), closedAt, deadline, notamNo);
89	    }
90	
91	    /**
92	     * 巡检开始：恰满15分钟未开始判定迟延并升级；低能见度须双人，单人记录不生效；
93	     * 归档后迟到巡检仅登记迟到事件。
94	     */
95	    @Transactional
96	    public InspectionResponse startInspection(long eventId, InspectionRequest request) {
97	        RunwayEvent event = mustFind(eventId);
98	        Instant now = clock.instant();
99	        if (event.status() == EventStatus.ARCHIVED) {
100	            InspectionRecord lateRecord = inspectionRepository.insert(new InspectionRecord(0L, eventId,
101	                    request.startedAt(), request.inspectorCount(), true, true, now));
102	            return new InspectionResponse(lateRecord.id(), eventId, true, event.escalated(), true,
103	                    event.status().name());
104	        }
105	        if (event.status() == EventStatus.REOPENED) {
106	            throw ApiException.conflict("EVENT_NOT_ACTIVE", "事件已恢复开放，不再受理巡检");
107	        }
108	        boolean late = !request.startedAt().isBefore(event.inspectionDeadline());
109	        boolean lowVisibility = weatherRepository.findLatestAtOrBefore(event.runwayId(), request.startedAt())
110	                .map(reading -> reading.rvrMeters() < properties.lowVisibilityRvrThreshold())
111	                .orElse(false);
112	        if (lowVisibility && request.inspectorCount() < 2) {
113	            throw ApiException.unprocessable("LOW_VISIBILITY_REQUIRES_DUAL",
114	                    "低能见度期间巡检须双人执行，单人记录不生效");
115	        }
116	        InspectionRecord record = inspectionRepository.insert(new InspectionRecord(0L, eventId,
117	                request.startedAt(), request.inspectorCount(), late, false, now));
118	        boolean escalated = event.escalated() || late;
119	        EventStatus newStatus = event.status() == EventStatus.CLOSED ? EventStatus.INSPECTING : event.status();
120	        eventRepository.updateStatus(eventId, newStatus, escalated, event.assessmentType(), false, now);
121	        return new InspectionResponse(record.id(), eventId, late, escalated, false, newStatus.name());
122	    }
123	
124	    /**
125	     * 巡检评估：摩擦系数低于0.35持续关闭，恰0.35合格；requestId 幂等。
126	     */
127	    public AssessmentResponse assess(long eventId, AssessmentRequest request) {
128	        String fingerprint = fingerprint(SCOPE_ASSESSMENT, request.requestId(), String.valueOf(eventId),
129	                request.frictionCoefficient().toPlainString(), request.assessmentType().name(),
130	                request.assessedAt().toString());
131	        try {
132	            return idempotencyExecutor.execute(SCOPE_ASSESSMENT, request.requestId(), fingerprint,
133	                    () -> doAssess(eventId, request), AssessmentResponse.class);
134	        } catch (DuplicateKeyException e) {
135	            AssessmentResponse replayed = idempotencyExecutor.tryReplay(SCOPE_ASSESSMENT, request.requestId(),
136	                    fingerprint, AssessmentResponse.class);
137	            if (replayed != null) {
138	                return replayed;
139	            }
140	            throw e;
141	        }
142	    }
143	
144	    private AssessmentResponse doAssess(long eventId, AssessmentRequest request) {
145	        RunwayEvent event = mustFind(eventId);
146	        requireActive(event, "评估");
147	        boolean passed = request.frictionCoefficient().compareTo(properties.frictionPassThreshold()) >= 0;
148	        List<AssessmentRecord> history = assessmentRepository.findByEventIdOrderByAssessedAt(eventId);
149	        boolean retest = history.stream().anyMatch(a -> a.assessmentType() == AssessmentType.REPAIR_REQUIRED);
150	        AssessmentRecord record = assessmentRepository.insert(new AssessmentRecord(0L, eventId,
151	                request.frictionCoefficient(), request.assessmentType(), request.assessedAt(), passed, retest,
152	                request.requestId(), clock.instant()));
153	        eventRepository.updateStatus(eventId, EventStatus.ASSESSED, event.escalated(), request.assessmentType(),
154	                false, clock.instant());
155	        return new AssessmentResponse(record.id(), eventId, passed, retest, EventStatus.ASSESSED.name());
156	    }
157	
158	    /**
159	     * 恢复开放：与航行通告发布在同一事务内完成；修复类须复测合格；requestId 幂等。
160	     */
161	    public ReopenResponse reopen(long eventId, ReopenRequest request) {
162	        String fingerprint = fingerprint(SCOPE_REOPEN, request.requestId(), String.valueOf(eventId),
163	                request.reopenedAt().toString());
164	        try {
165	            return idempotencyExecutor.execute(SCOPE_REOPEN, request.requestId(), fingerprint,
166	                    () -> doReopen(eventId, request), ReopenResponse.class);
167	        } catch (DuplicateKeyException e) {
168	            ReopenResponse replayed = idempotencyExecutor.tryReplay(SCOPE_REOPEN, request.requestId(),
169	                    fingerprint, ReopenResponse.class);
170	            if (replayed != null) {
171	                return replayed;
172	            }
173	            throw e;
174	        }
175	    }
176	
177	    private ReopenResponse doReopen(long eventId, ReopenRequest request) {
178	        RunwayEvent event = mustFind(eventId);
179	        if (event.status() == EventStatus.ARCHIVED) {
180	            throw ApiException.conflict("EVENT_ARCHIVED", "事件已归档，不得恢复开放");
181	        }
182	        if (event.status() == EventStatus.REOPENED) {
183	            throw ApiException.conflict("EVENT_ALREADY_REOPENED", "事件已恢复开放");
184	        }
185	        List<AssessmentRecord> history = assessmentRepository.findByEventIdOrderByAssessedAt(eventId);
186	        if (history.isEmpty()) {
187	            throw ApiException.unprocessable("ASSESSMENT_REQUIRED", "尚无评估记录，不得恢复开放");
188	        }
189	        int lastRepairIndex = -1;
190	        for (int i = 0; i < history.size(); i++) {
191	            if (history.get(i).assessmentType() == AssessmentType.REPAIR_REQUIRED) {
192	                lastRepairIndex = i;
193	            }
194	        }
195	        if (lastRepairIndex >= 0) {
196	            boolean passAfterRepair = history.subList(lastRepairIndex + 1, history.size()).stream()
197	                    .anyMatch(AssessmentRecord::passed);
198	            if (!passAfterRepair) {
199	                throw ApiException.unprocessable("REPAIR_RETEST_REQUIRED", "修复类评估须复测合格方可开放");
200	            }
201	        }
202	        if (!history.getLast().passed()) {
203	            throw ApiException.unprocessable("FRICTION_BELOW_THRESHOLD", "摩擦系数低于0.35，须持续关闭");
204	        }
205	        Instant now = clock.instant();
206	        eventRepository.updateStatus(eventId, EventStatus.REOPENED, event.escalated(), event.assessmentType(),
207	                true, now);
208	        String notamNo = "NTM-R-" + eventId;
209	        notamRepository.insert(new NotamRecord(0L, eventId, event.runwayId(), NotamAction.REOPEN,
210	                notamNo, request.reopenedAt()));
211	        return new ReopenResponse(eventId, EventStatus.REOPENED.name(), request.reopenedAt(), notamNo);
212	    }
213	
214	    /**
215	     * 归档：终态；重复归档返回幂等成功。
216	     */
217	    @Transactional
218	    public ArchiveResponse archive(long eventId) {
219	        RunwayEvent event = mustFind(eventId);
220	        if (event.status() == EventStatus.ARCHIVED) {
221	            return new ArchiveResponse(eventId, EventStatus.ARCHIVED.name(), true);
222	        }
223	        if (event.status() != EventStatus.REOPENED && event.status() != EventStatus.ASSESSED) {
224	            throw ApiException.conflict("EVENT_NOT_ARCHIVABLE", "仅恢复开放或持续关闭（已评估）状态可归档");
225	        }
226	        eventRepository.updateStatus(eventId, EventStatus.ARCHIVED, event.escalated(), event.assessmentType(),
227	                true, clock.instant());
228	        return new ArchiveResponse(eventId, EventStatus.ARCHIVED.name(), false);
229	    }
230	
231	    /**
232	     * 事件详情：状态时间线由事件、巡检、评估与通告记录复算。
233	     */
234	    @Transactional(readOnly = true)
235	    public EventDetailResponse getDetail(long eventId) {
236	        RunwayEvent event = mustFind(eventId);
237	        List<TimelineEntry> timeline = new ArrayList<>();
238	        timeline.add(new TimelineEntry("REPORTED", event.reportedAt(),
239	                "接报" + event.eventType() + "，触发临时关闭"));
240	        for (NotamRecord notam : notamRepository.findByEventId(eventId)) {
241	            timeline.add(new TimelineEntry(notam.action() == NotamAction.CLOSE ? "CLOSED_NOTAM" : "REOPEN_NOTAM",
242	                    notam.publishedAt(), "航行通告 " + notam.noticeNo()));
243	        }
244	        boolean escalatedMarked = false;
245	        for (InspectionRecord inspection : inspectionRepository.findByEventId(eventId)) {
246	            if (inspection.recordedAfterArchive()) {
247	                timeline.add(new TimelineEntry("LATE_INSPECTION_RECORDED", inspection.startedAt(),
248	                        "归档后迟到巡检记录，仅登记"));
249	                continue;
250	            }
251	            timeline.add(new TimelineEntry("INSPECTION_STARTED", inspection.startedAt(),
252	                    "巡检开始，人数" + inspection.inspectorCount() + (inspection.late() ? "，迟延" : "")));
253	            if (inspection.late() && !escalatedMarked) {
254	                timeline.add(new TimelineEntry("ESCALATED", inspection.startedAt(), "巡检迟延，事件升级"));
255	                escalatedMarked = true;
256	            }
257	        }
258	        for (AssessmentRecord assessment : assessmentRepository.findByEventIdOrderByAssessedAt(eventId)) {
259	            timeline.add(new TimelineEntry("ASSESSED", assessment.assessedAt(),
260	                    "摩擦系数" + assessment.frictionCoefficient().toPlainString()
261	                            + (assessment.passed() ? "，合格" : "，不合格持续关闭")
262	                            + (assessment.retest() ? "（复测）" : "")));
263	        }
264	        if (event.status() == EventStatus.REOPENED) {
265	            notamRepository.findByEventId(eventId).stream()
266	                    .filter(n -> n.action() == NotamAction.REOPEN)
267	                    .findFirst()
268	                    .ifPresent(n -> timeline.add(new TimelineEntry("REOPENED", n.publishedAt(), "恢复开放")));
269	        }
270	        if (event.status() == EventStatus.ARCHIVED) {
271	            timeline.add(new TimelineEntry("ARCHIVED", event.updatedAt(), "事件归档（终态）"));
272	        }
273	        timeline.sort(Comparator.comparing(TimelineEntry::at));
274	        return new EventDetailResponse(event.id(), event.runwayId(), event.eventType().name(),
275	                event.status().name(), event.reportedAt(), event.closedAt(), event.inspectionDeadline(),
276	                event.escalated(), timeline);
277	    }
278	
279	    /**
280	     * 摩擦系数轨迹：按评估时间排序。
281	     */
282	    @Transactional(readOnly = true)
283	    public List<FrictionPoint> getFrictionTrajectory(long eventId) {
284	        mustFind(eventId);
285	        return assessmentRepository.findByEventIdOrderByAssessedAt(eventId).stream()
286	                .map(a -> new FrictionPoint(a.id(), a.frictionCoefficient(), a.assessmentType().name(),
287	                        a.passed(), a.retest(), a.assessedAt()))
288	                .toList();
289	    }
290	
291	    /**
292	     * 通告记录。
293	     */
294	    @Transactional(readOnly = true)
295	    public List<NotamView> getNotams(long eventId) {
296	        mustFind(eventId);
297	        return notamRepository.findByEventId(eventId).stream()
298	                .map(n -> new NotamView(n.id(), n.eventId(), n.action().name(), n.noticeNo(), n.publishedAt()))
299	                .toList();
300	    }
301	
302	    /**
303	     * 上报气象读数（合成数据）。
304	     */
305	    @Transactional
306	    public WeatherResponse addWeatherReading(WeatherRequest request) {
307	        WeatherReading saved = weatherRepository.insert(new WeatherReading(0L, request.runwayId(),
308	                request.rvrMeters(), request.recordedAt()));
309	        return new WeatherResponse(saved.id(), saved.runwayId(), saved.rvrMeters(), saved.recordedAt());
310	    }
311	
312	    /**
313	     * 按跑道查询气象读数。
314	     */
315	    @Transactional(readOnly = true)
316	    public List<WeatherResponse> listWeatherReadings(String runwayId) {
317	        return weatherRepository.findByRunwayId(runwayId).stream()
318	                .map(w -> new WeatherResponse(w.id(), w.runwayId(), w.rvrMeters(), w.recordedAt()))
319	                .toList();
320	    }
321	
322	    private RunwayEvent mustFind(long eventId) {
323	        return eventRepository.findById(eventId)
324	                .orElseThrow(() -> ApiException.notFound("跑道事件不存在: " + eventId));
325	    }
326	
327	    private void requireActive(RunwayEvent event, String operation) {
328	        if (event.status() == EventStatus.ARCHIVED) {
329	            throw ApiException.conflict("EVENT_ARCHIVED", "事件已归档，不再受理" + operation);
330	        }
331	        if (event.status() == EventStatus.REOPENED) {
332	            throw ApiException.conflict("EVENT_NOT_ACTIVE", "事件已恢复开放，不再受理" + operation);
333	        }
334	    }
335	
336	    private boolean isActiveEventConflict(DuplicateKeyException e) {
337	        String message = String.valueOf(e.getMessage()).toLowerCase(Locale.ROOT);
338	        return message.contains("uk_runway_event_active");
339	    }
340	
341	    private String fingerprint(String... parts) {
342	        try {
343	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
344	            byte[] hash = digest.digest(String.join("|", parts).getBytes(StandardCharsets.UTF_8));
345	            StringBuilder hex = new StringBuilder(hash.length * 2);
346	            for (byte b : hash) {
347	                hex.append(Character.forDigit((b >> 4) & 0xF, 16)).append(Character.forDigit(b & 0xF, 16));
348	            }
349	            return hex.toString();
350	        } catch (NoSuchAlgorithmException e) {
351	            throw new IllegalStateException("SHA-256 不可用", e);
352	        }
353	    }
354	}
